#!/bin/zsh
# 다듬기 단계의 원본 생성(바다 장식, 캐릭터 동작). 이름을 인자로 주면 그것만 만든다.
cd /Users/iyeonsang/Desktop/game/games/cat-angler
gfq() { uv run -q --project /Users/iyeonsang/Desktop/game/harness/tools gf --project /Users/iyeonsang/Desktop/game/games/cat-angler "$@" | tail -1 | python3 -c "import sys,json; d=json.loads(sys.stdin.read()); print(d.get('ok'), d.get('files'), d.get('cost_usd'), d.get('error'))"; }
STYLE="pixel art game asset in the exact art style of the reference image, very chunky large pixels, hard pixel edges, no anti-aliasing, thick dark outline, big simple shapes, two or three flat shading tones, minimal detail that survives at small size"
BG="Flat solid pure magenta #FF00FF background everywhere, no shadow, no water, no ground, no text, no labels, no grid lines"
typeset -A A P R
A[deco_shallow]=16:9; R[deco_shallow]=design/look/target.png; P[deco_shallow]="$STYLE: a sprite sheet of eight small shallow sea floor decorations in a 4 columns by 2 rows grid, each alone and centered in its cell with empty space around it, each with a flat bottom so it can stand on sand. Top row: (1) a short tuft of bright green seaweed blades, (2) a taller clump of wavy green and teal seaweed ribbons, (3) a tall slender kelp plant with broad leaves, dark teal and green, (4) a branching mint and pale teal coral. Bottom row: (5) a fan shaped teal coral, (6) a small rounded grey green rock with a patch of moss, (7) a wider low rock with two barnacles and a tiny seaweed sprout, (8) a pale cream and mint giant clam shell slightly open. Only cool colours: green, teal, mint, grey blue, cream. $BG."
A[deco_deep]=16:9; R[deco_deep]=design/look/target.png; P[deco_deep]="$STYLE: a sprite sheet of eight deep sea floor decorations in a 4 columns by 2 rows grid, each alone and centered in its cell with empty space around it, each with a flat bottom so it can stand on the sea floor. Top row: (1) a tall dark teal kelp plant with long wavy leaves, (2) another tall kelp with thinner blue green ribbons, (3) a grey blue boulder with dark cracks, (4) a cluster of slate blue rocks with a small teal anemone. Bottom row: (5) a dark indigo branching coral with glowing light blue tips, (6) a group of indigo tube sponges with glowing pale blue rims, (7) an open pale shell holding one glowing light blue pearl, (8) a small traditional Korean stone lantern, slate blue stone with a softly glowing pale blue light inside. Only cool colours: navy, indigo, slate blue, teal, pale blue, mint. Mysterious, not scary. $BG."
A[under_far]=4:1; R[under_far]=design/look/target.png; P[under_far]="A wide horizontal strip of flat single-colour silhouettes for a distant underwater parallax background, pixel art with chunky hard pixel edges and no anti-aliasing, in the manner of the faint sunken ruin silhouette in the middle of the reference image: an uneven rolling sea floor skyline with rock mounds, three clumps of tall kelp, two broken ancient pillars and one fallen lintel, a small arch. Everything filled with one single flat dark teal colour #28706F with no outline, no shading and no interior detail. The silhouette touches the bottom edge along the whole width and its skyline varies in height between one quarter and three quarters of the image height. Above it flat solid pure magenta #FF00FF. No text."
A[keepers_talk]=1:1; R[keepers_talk]=assets/raw/land/keepers.png; P[keepers_talk]="Edit this pixel art sprite sheet minimally. Keep all four characters exactly as they are: same positions, same sizes, same poses, same colours, same outlines, same magenta background. Change ONLY their mouths: the raccoon, the otter and the beaver each have their mouth clearly open in a small dark oval as if talking mid-word, and the heron has its beak clearly open with the lower beak dropped. Do not move, resize or redraw anything else."
A[longfish]=16:9; R[longfish]=design/look/target.png; P[longfish]="$STYLE: a sprite sheet of two long sea fish, one above the other, each alone with empty space around it, both in exact side view facing right and both with a perfectly straight horizontal body stretched from the left edge area to the right edge area (no curl, no bend, tail pointing straight left). Top: a hairtail cutlassfish, a very long thin flat ribbon body, pale silver mint with a darker teal back line, a long low dorsal fin along the whole back, big round eye, pointed jaw, the tail tapering to a thin point. Bottom: an oarfish, a very long thick ribbon body, pale blue silver with a few glowing light blue dots, a tall teal crest of fin rays on the head, a long teal fin along the whole back, two long thin trailing pelvic fin rays, big round eye. Only cool colours. Friendly and mysterious. $BG."
A[crate]=1:1; R[crate]=design/look/target.png; P[crate]="$STYLE, drawn as a very low resolution 20 pixel tall sprite with huge chunky pixels: one simple square wooden shipping crate seen straight from the front, warm brown planks, a darker brown frame around the edge and one diagonal brace plank, a short piece of cream rope on top. Big flat colour areas, no small details. Single object centered. $BG."
names=(${(k)A}); [[ -n "$1" ]] && names=("$@")
for k in $names; do
  gfq gen edit "${P[$k]}" --image ${R[$k]} --aspect ${A[$k]} --resolution 1K --out assets/raw/polish --name $k &
done
wait
